//! ⛽️ Original in-place payload projection admits frame, canonical page and scalar source separately.
use super::*;
impl RetainedPayloadBuilder{
 /// 🪺️ Quotes only initialized frame fields and the actual allocation; original payload slots stay uninitialized.
 pub fn boxed_birth_demands()->RetirementDemand{RetirementDemand{copy_bytes:Self::empty_carrier_copy_bytes()+2*size_of::<Box<Self>>(),capacity_bytes:size_of::<Self>(),depth:1,..Default::default()}}
 /// 🎟️ Allocates stable original storage after admission without forming or moving its payload array.
 pub fn admit_boxed(stream:JobPayloadStream,cx:&mut impl JobPayloadStep)->Result<Option<Box<Self>>,ValueError>{let demand=Self::boxed_birth_demands();if cx.is_cancelled()||!Self::permits(cx,demand){return Ok(None)}let mut storage=Box::<Self>::new_uninit();let target=storage.as_mut_ptr();unsafe{std::ptr::addr_of_mut!((*target).stream).write(stream);std::ptr::addr_of_mut!((*target).initialized).write(0);std::ptr::addr_of_mut!((*target).ready).write(false);std::ptr::addr_of_mut!((*target).sealed).write(false);std::ptr::addr_of_mut!((*target).staged).write(None);}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,retained_capacity_bytes:demand.capacity_bytes,..Default::default()})?;Ok(Some(unsafe{storage.assume_init()}))}
 pub fn staged_page_len(&self)->Option<usize>{self.staged.as_ref().map(|(_,_,length)|*length)}
 pub fn staged_page_remaining(&self)->usize{self.staged.as_ref().map_or(0,|(_,source,length)|source.allocated_capacity_bytes()-*length)}
 pub fn staged_backing_identity(&self)->Option<*const MaybeUninit<u8>>{self.staged.as_ref().map(|(_,source,_)|source.backing_identity())}
 pub fn staged_page_birth_demands(&self)->Result<RetirementDemand,ValueError>{let payload=self.original().ok_or_else(||ValueError::literal(ValueRefusalKind::InvalidValue,"original payload bindings are not initialized"))?;if self.sealed||payload.page_count>=JOB_PAYLOAD_OPERATION_PAGES{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original payload cannot admit another page"))}Ok(RetirementDemand{copy_bytes:size_of::<Option<(Arc<JobPayloadOperationLedger>,JobPayloadPageSource,usize)>>()+JobPayloadOperationLedger::reservation_copy_bytes(),capacity_bytes:if self.staged.is_none(){JOB_PAYLOAD_PAGE_BYTES}else{0},depth:3,..Default::default()})}
 /// 🧱️ Creates exactly one canonical page on its own admitted opportunity.
 pub fn begin_staged_page_funded(&mut self,cx:&mut impl JobPayloadStep)->Result<bool,ValueError>{if self.staged.is_some(){return Ok(true)}let demand=self.staged_page_birth_demands()?;if cx.is_cancelled()||cx.payload_page_granted()||!Self::permits(cx,demand){return Ok(false)}let payload=self.original().unwrap();if payload.ledger.as_ref().is_some_and(|ledger|!Arc::ptr_eq(ledger,cx.payload_ledger())){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original staged payload requires the same ledger"))}cx.payload_ledger().reserve(payload.stream,JOB_PAYLOAD_PAGE_BYTES).map_err(|_|ValueError::literal(ValueRefusalKind::OwnershipLimit,"original staged page ledger refused"))?;self.staged=Some((Arc::clone(cx.payload_ledger()),JobPayloadPageSource::new(),0));cx.grant_payload_page();cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,retained_capacity_bytes:demand.capacity_bytes,..Default::default()})?;Ok(true)}
 pub fn staged_source_demands(&self,source:&(impl JobPayloadStagedSource+?Sized),cursor_copy_bytes:usize)->Result<RetirementDemand,ValueError>{if self.staged.is_none()||source.byte_len()>self.staged_page_remaining(){return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original staged source exceeds its paid page"))}let copy_bytes=source.copy_byte_demand().map_err(staged_fault)?.checked_add(source.byte_len()).and_then(|v|v.checked_add(size_of::<usize>())).and_then(|v|v.checked_add(cursor_copy_bytes)).ok_or_else(||ValueError::literal(ValueRefusalKind::OwnershipLimit,"original staged source copy overflow"))?;let depth=source.depth_demand().map_err(staged_fault)?.checked_add(1).ok_or_else(||ValueError::literal(ValueRefusalKind::DepthLimit,"original staged source depth overflow"))?;Ok(RetirementDemand{copy_bytes,depth,..Default::default()})}
 /// ✍️ Produces a canonical source directly into the original admitted page.
 pub fn write_staged_source_funded(&mut self,cx:&mut impl JobPayloadStep,source:&(impl JobPayloadStagedSource+?Sized),cursor_copy_bytes:usize)->Result<bool,ValueError>{let demand=self.staged_source_demands(source,cursor_copy_bytes)?;if cx.is_cancelled()||!Self::permits(cx,demand){return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})?;let(_,page,length)=self.staged.as_mut().unwrap();let end=*length+source.byte_len();source.write_bytes(&mut page.storage[*length..end]).map_err(staged_fault)?;*length=end;Ok(true)}
 pub fn staged_commit_demands(&self)->Result<RetirementDemand,ValueError>{if self.staged.is_none(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original staged page is absent"))}Ok(RetirementDemand{copy_bytes:size_of::<Option<(Arc<JobPayloadOperationLedger>,JobPayloadPageSource,usize)>>()+size_of::<Option<JobPayloadPage>>()+size_of::<Option<Arc<JobPayloadOperationLedger>>>()+2*size_of::<usize>(),depth:3,..Default::default()})}
 /// 📤️ Installs this same original page and ledger without moving the payload header.
 pub fn commit_staged_page_funded(&mut self,cx:&mut impl JobPayloadStep)->Result<bool,ValueError>{let demand=self.staged_commit_demands()?;if cx.is_cancelled()||!Self::permits(cx,demand){return Ok(false)}let(ledger,source,length)=self.staged.take().unwrap();let payload=unsafe{self.original.assume_init_mut()};let index=payload.page_count;if index>=JOB_PAYLOAD_OPERATION_PAGES||payload.pages[index].is_some(){self.staged=Some((ledger,source,length));return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original payload slot is occupied"))}payload.pages[index]=Some(JobPayloadPage{source,length});payload.page_count+=1;payload.length+=length;if payload.ledger.is_none(){*payload.ledger=Some(ledger)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})?;Ok(true)}
 pub(super) fn staged_retirement_demands(&self)->Result<RetirementDemand,ValueError>{let(_,source,_)=self.staged.as_ref().unwrap();Ok(RetirementDemand{copy_bytes:size_of::<Option<(Arc<JobPayloadOperationLedger>,JobPayloadPageSource,usize)>>()+size_of::<Option<Arc<JobPayloadOperationLedger>>>()+JobPayloadOperationLedger::reservation_copy_bytes(),release_bytes:source.allocated_capacity_bytes(),depth:3,..Default::default()})}
 pub(super) fn close_staged_granted(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let demand=self.staged_retirement_demands()?;if !JobPayloadAuthority::permits(grant,demand){return Ok(RetainedCloneStep::Progress(Default::default()))}let(ledger,source,_)=self.staged.take().unwrap();ledger.release(self.stream,source.allocated_capacity_bytes());let payload=unsafe{self.original.assume_init_mut()};if payload.ledger.is_none(){*payload.ledger=Some(ledger)}drop(source);Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,released_bytes:demand.release_bytes,..Default::default()}))}
 /// ♻️ Quotes the separate physical return of an already terminal boxed owner.
 pub fn boxed_release_demands()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<Box<Self>>>(),release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
fn staged_fault(_:JobPayloadAdmissionFault)->ValueError{ValueError::literal(ValueRefusalKind::OwnershipLimit,"original staged payload source refused")}
